import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { toast } from '../libs/toast';
import { FaSave, FaTimes } from 'react-icons/fa';
import axios from 'axios';
import './AnnouncementForm.css';
import DatePicker from 'react-multi-date-picker';
import TimePicker from 'react-multi-date-picker/plugins/time_picker';
import persian from 'react-date-object/calendars/persian';
import DateObject from 'react-date-object';
import gregorian from 'react-date-object/calendars/gregorian';
import { normalizeTime } from '../utils/locale';

const AnnouncementForm: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const isEdit = Boolean(id);

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    date: '',
    time: '',
    location: '',
    programId: '',
    actorIds: [] as string[]
  });
  const [status, setStatus] = useState<'draft' | 'published'>('draft');

  const [loading, setLoading] = useState(false);
  const [programs, setPrograms] = useState<any[]>([]);
  const [actors, setActors] = useState<any[]>([]);
  const [actorRoles, setActorRoles] = useState<Record<string, string>>({});

  useEffect(() => {
    if (isEdit) {
      fetchAnnouncement();
    }
    // Load programs and actors
    const loadOptions = async () => {
      try {
        const [progRes, actRes] = await Promise.all([
          axios.get('/api/programs', { params: { limit: 100 } }),
          axios.get('/api/actors', { params: { limit: 100 } })
        ]);
        setPrograms(progRes.data);
        setActors(actRes.data);
      } catch (err) {
        // silent fail
      }
    };
    loadOptions();
    const draft = localStorage.getItem('announcement_draft');
    if (!isEdit && draft) {
      try {
        const d = JSON.parse(draft);
        setFormData(d.formData || formData);
        setStatus(d.status || 'draft');
      } catch { }
    }
  }, [id]);

  const fetchAnnouncement = async () => {
    try {
      const response = await axios.get(`/api/announcements/${id}`);
      const announcement = response.data;
      setFormData({
        title: announcement.title,
        description: announcement.description,
        date: announcement.date,
        time: announcement.time,
        location: announcement.venue,
        programId: announcement.program_id ? String(announcement.program_id) : '',
        actorIds: announcement.actors?.map((actor: any) => actor.id) || []
      });
    } catch (error) {
      toast.error('خطا در دریافت اطلاعات آفیش');
      navigate('/announcements');
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    setTimeout(() => {
      localStorage.setItem('announcement_draft', JSON.stringify({ formData: { ...formData, [name]: value }, status }));
    }, 0);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title || !formData.description || !formData.date || !formData.time || !formData.location) {
      toast.error('لطفاً فیلدهای الزامی را پر کنید');
      return;
    }

    setLoading(true);

    try {
      const token = localStorage.getItem('token');
      const payload = {
        title: formData.title,
        description: formData.description,
        program_id: formData.programId || null,
        date: formData.date,
        time: normalizeTime(formData.time),
        venue: formData.location,
        price: null,
        actor_ids: formData.actorIds || [],
        actor_roles: (formData.actorIds || []).map(aid => actorRoles[aid] || null),
        status,
      };

      if (isEdit) {
        await axios.put(`/api/announcements/${id}`, payload, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        });
        toast.success('آفیش با موفقیت ویرایش شد');
      } else {
        await axios.post('/api/announcements', payload, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        });
        toast.success('آفیش با موفقیت ایجاد شد');
      }

      navigate('/announcements');
      localStorage.removeItem('announcement_draft');
    } catch (error) {
      toast.error(isEdit ? 'خطا در ویرایش آفیش' : 'خطا در ایجاد آفیش');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="announcement-form-container">
      <h2>{isEdit ? 'ویرایش آفیش' : 'ایجاد آفیش جدید'}</h2>

      <form onSubmit={handleSubmit} className="announcement-form">
        <div className="form-group">
          <label htmlFor="title">عنوان آفیش *</label>
          <input
            type="text"
            id="title"
            name="title"
            value={formData.title}
            onChange={handleInputChange}
            className="form-input"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="status">وضعیت</label>
          <select id="status" value={status} onChange={(e) => { setStatus(e.target.value as any); localStorage.setItem('announcement_draft', JSON.stringify({ formData, status: e.target.value })); }} className="form-select">
            <option value="draft">پیش‌نویس</option>
            <option value="published">منتشر شده</option>
          </select>
        </div>

        <div className="form-group">
          <label htmlFor="description">توضیحات</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleInputChange}
            className="form-textarea"
            rows={4}
          />
        </div>

        <div className="form-row">
          <div className="form-group">
            <label htmlFor="date">تاریخ *</label>
            <DatePicker
              calendar={persian}
              inputClass="form-input"
              value={formData.date ? new DateObject({ date: new Date(formData.date) }).convert(persian) : null}
              onChange={(val: any) => {
                if (!val) {
                  setFormData(prev => ({ ...prev, date: '' }));
                  return;
                }
                try {
                  const obj = val instanceof DateObject ? val : new DateObject(val);
                  const greg = obj.convert(gregorian).format('YYYY-MM-DD');
                  setFormData(prev => ({ ...prev, date: greg }));
                } catch {
                  toast.error('خطا در تنظیم تاریخ');
                }
              }}
              format="YYYY/MM/DD"
              placeholder="انتخاب تاریخ به تقویم شمسی"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="time">زمان *</label>
            <DatePicker
              calendar={persian}
              format="HH:mm"
              inputClass="form-input"
              disableDayPicker
              plugins={[<TimePicker hideSeconds />]}
              value={formData.time || undefined}
              onChange={(val: any) => {
                if (!val) {
                  setFormData(prev => ({ ...prev, time: '' }));
                  return;
                }
                try {
                  const obj = val instanceof DateObject ? val : new DateObject(val);
                  const time = obj.format('HH:mm');
                  setFormData(prev => ({ ...prev, time }));
                } catch {
                  toast.error('خطا در تنظیم زمان');
                }
              }}
              placeholder="انتخاب زمان (فارسی)"
              required
            />
          </div>
        </div>

        <div className="form-group">
          <label htmlFor="location">مکان</label>
          <input
            type="text"
            id="location"
            name="location"
            value={formData.location}
            onChange={handleInputChange}
            className="form-input"
          />
        </div>

        <div className="form-group">
          <label htmlFor="programId">برنامه مرتبط</label>
          <select
            id="programId"
            name="programId"
            value={formData.programId}
            onChange={handleInputChange}
            className="form-select"
          >
            <option value="">بدون برنامه</option>
            {programs.map((p: any) => (
              <option key={p.id} value={String(p.id)}>{p.title}</option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label>انتخاب عوامل و نقش در برنامه</label>
          <div className="actors-grid">
            {actors.map((a: any) => {
              const checked = formData.actorIds.includes(String(a.id));
              return (
                <div className="actor-checkbox" key={a.id}>
                  <input
                    type="checkbox"
                    checked={checked}
                    onChange={(e) => {
                      const isChecked = e.target.checked;
                      setFormData(prev => ({
                        ...prev,
                        actorIds: isChecked
                          ? [...prev.actorIds, String(a.id)]
                          : prev.actorIds.filter(id => id !== String(a.id))
                      }));
                    }}
                  />
                  <label>{a.name} <span className="actor-role">({a.role})</span></label>
                  {checked && (
                    <input
                      type="text"
                      placeholder="نقش در برنامه"
                      value={actorRoles[String(a.id)] || ''}
                      onChange={(e) => setActorRoles(prev => ({ ...prev, [String(a.id)]: e.target.value }))}
                      className="form-input"
                      style={{ maxWidth: '180px' }}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </div>

        <div className="form-actions">
          <button type="submit" className="save-btn" disabled={loading}>
            {loading ? (
              <span>در حال ذخیره...</span>
            ) : (
              <>
                <FaSave />
                {isEdit ? 'ویرایش آفیش' : 'ایجاد آفیش'}
              </>
            )}
          </button>

          <button
            type="button"
            onClick={() => navigate('/announcements')}
            className="cancel-btn"
            disabled={loading}
          >
            <FaTimes />
            انصراف
          </button>
          <button
            type="button"
            onClick={() => { localStorage.setItem('announcement_draft', JSON.stringify({ formData, status })); toast.success('پیش‌نویس ذخیره شد'); }}
            className="save-btn"
            disabled={loading}
            style={{ marginInlineStart: '8px' }}
          >
            ذخیره پیش‌نویس
          </button>
        </div>
      </form>
    </div>
  );
};

export default AnnouncementForm;
